import type { OrderStreamMeta, Order, PublicConfig } from "@kitchensched/contracts";
import { fetchJson } from "./http";

/**
 * Browser-playable scenario bundles, generated by `site/scripts/gen-scenarios.mts`
 * into `site/public/scenarios/` and committed.
 *
 * They resolve against `document.baseURI` exactly like `results/` does (see
 * `lib/results.ts`): hash routing never changes the document path, so this
 * works at `/`, under a `/<repo>/` project page, and on localhost.
 */
export const SCENARIOS_ROOT = new URL("scenarios/", document.baseURI);

/** One card of the scenario picker (`scenarios/index.json`). */
export interface ScenarioSummary {
  tier: string;
  label: string;
  difficulty: string;
  scenario_id: string;
  end_at_ms: number;
  station_count: number;
  order_count: number;
  /** Sum of every order's value: the revenue a perfect kitchen would book. */
  book_value_minor: number;
  /** Score the greedy baseline reaches on this exact stream and policy seed. */
  greedy_score_minor: number;
  url: string;
}

export interface ScenarioIndex {
  schema: string;
  scenarios: ScenarioSummary[];
}

export interface ScenarioBundle {
  schema: string;
  tier: string;
  config: PublicConfig;
  orders: Order[];
  /** Public stream metadata; also the header field of a downloaded replay. */
  stream: OrderStreamMeta & { tag?: string };
  policy_seed: number;
  reference: { greedy_score_minor: number; book_value_minor: number };
}

export function scenarioUrl(relative: string): string {
  return new URL(relative, SCENARIOS_ROOT).href;
}

export function loadScenarioIndex(): Promise<ScenarioIndex> {
  return fetchJson<ScenarioIndex>(scenarioUrl("index.json"));
}

export function loadScenarioBundle(summary: ScenarioSummary): Promise<ScenarioBundle> {
  return fetchJson<ScenarioBundle>(scenarioUrl(summary.url));
}

/**
 * The bundle's `stream` carries a `tag` the contract does not declare; a
 * replay header must be byte-compatible with the host's artifacts, so the
 * replay meta is rebuilt from the declared fields only.
 */
export function orderStreamMeta(bundle: ScenarioBundle): OrderStreamMeta {
  const { visibility, seed, generator_version } = bundle.stream;
  return seed === undefined
    ? { visibility, generator_version }
    : { visibility, seed, generator_version };
}

/* --------------------------- local best score --------------------------- */

/**
 * The player's own record per tier. Practice only — nothing here is uploaded,
 * and the leaderboard is unaffected by it.
 */
export function bestKey(tier: string): string {
  return `kitchensched-best-${tier}`;
}

export function readBest(tier: string): number | null {
  try {
    const raw = window.localStorage.getItem(bestKey(tier));
    if (raw === null) return null;
    const value = Number(raw);
    return Number.isFinite(value) ? value : null;
  } catch {
    return null;
  }
}

/** Writes only on a strictly better score; returns the stored best afterwards. */
export function writeBest(tier: string, scoreMinor: number): number {
  const previous = readBest(tier);
  const best = previous === null || scoreMinor > previous ? scoreMinor : previous;
  try {
    window.localStorage.setItem(bestKey(tier), String(best));
  } catch {
    // Private-mode / quota failures must never break the end screen.
  }
  return best;
}
